using System.Data; using Garage.DAL; using Garage.DTO; namespace Garage.BUS; public class GarageService {readonly GarageRepository r=new(); public DataTable Parts()=>r.Parts();public DataTable Customers()=>r.Customers();public DataTable Repairs()=>r.Repairs();public DataTable SearchCars(string k)=>r.SearchCars(k);public void AddCustomerCar(string n,string p,string a,string b,string h,int y){if(string.IsNullOrWhiteSpace(n)||string.IsNullOrWhiteSpace(b))throw new ArgumentException("Tên chủ xe và biển số bắt buộc.");r.AddCustomerCar(n,p,a,b,h,y);}public void AddPart(string n,decimal p,int s){if(string.IsNullOrWhiteSpace(n)||p<0||s<0)throw new ArgumentException("Thông tin phụ tùng không hợp lệ.");r.AddPart(n,p,s);}public void CreateRepair(string b,string n,List<RepairItem> i)=>r.CreateRepair(b,n,i);public void Pay(int id)=>r.Pay(id);}